from bloomerp.models.communication.voip.voip_connection import VoIPConnection
from django.http import HttpResponse
from django.test import override_settings
from bloomerp.config.definition import BloomerpConfig
from bloomerp.tests.base import (
    BloomerpModelViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestCreateVoIpconnectionView(BloomerpModelViewTestCase):
    """Tests class `CreateVoIPConnectionView` from `bloomerp/views/communication/create_voip_connection.py`."""

    view_name = "add"
    model = VoIPConnection

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Describe the observable request contracts for this endpoint."""
        # Add only the route scenarios this callable needs.
        return [
            RequestScenario(
                name="Offer Twilio setup to staff",
                user=self.normal_user,
                expected=ExpectedResult(
                    response_validators=[self.contains_text("Twilio")]
                ),
            ),
            RequestScenario(
                name="Save encrypted carrier configuration",
                user=self.normal_user,
                method="POST",
                prepare=self.configure_twilio,
                expected=ExpectedResult(response_validators=[self.validate_saved]),
            ),
        ]

    def configure_twilio(self, scenario: RequestScenario) -> None:
        """Advance the actual wizard and submit only typed carrier settings."""
        self.enterContext(
            override_settings(
                BLOOMERP_CONFIG=BloomerpConfig(email_secret_key="test-key")
            )
        )
        self.client.force_login(self.normal_user)
        self.client.post(
            self.get_endpoint(self.view_name, None), {"provider": "twilio"}
        )
        scenario.data = {
            "name": "Twilio test",
            "account_sid": "AC" + "1" * 32,
            "auth_token": "test-auth-token",
            "api_key_sid": "",
            "api_key_secret": "",
            "application_sid": "",
            "public_url": "https://example.test",
        }

    def validate_saved(self, response: HttpResponse) -> bool:
        """Verify encrypted persistence and absence of secrets in response/session state."""
        connection = self.model.objects.get(name="Twilio test")
        return (
            connection.get_credentials()["auth_token"] == "test-auth-token"
            and "test-auth-token" not in connection.credentials
            and "test-auth-token" not in response.content.decode()
            and "test-auth-token" not in str(dict(self.client.session))
        )
